package main

import (
	"context"
	"embed"
	"io/fs"
	"log/slog"
	"os"

	"github.com/troubleman96/tengeneza-cv-desktop/internal/desktop"
	"github.com/wailsapp/wails/v2"
	"github.com/wailsapp/wails/v2/pkg/options"
	"github.com/wailsapp/wails/v2/pkg/options/assetserver"
)

// The web assets are generated by `pnpm --dir frontend vite:build` before the
// Go binary is built. The sample fixtures are source-controlled, fictional CVs.
//
//go:embed frontend/dist/public
var frontendAssets embed.FS

//go:embed examples/sample-cvs/*.json
var sampleCVAssets embed.FS

type App struct{ desktop *desktop.DesktopApp }

func main() {
	web, err := fs.Sub(frontendAssets, "frontend/dist/public")
	if err != nil {
		slog.Error("web assets are missing; build the frontend first", "error", err)
		os.Exit(1)
	}
	samples, err := fs.Sub(sampleCVAssets, "examples/sample-cvs")
	if err != nil {
		slog.Error("sample CV fixtures are unavailable", "error", err)
		os.Exit(1)
	}

	service := desktop.New(web, samples, slog.Default())
	application := &App{desktop: service}
	if err := wails.Run(&options.App{
		Title:                    "Tengeneza CV",
		Width:                    1440,
		Height:                   920,
		MinWidth:                 960,
		MinHeight:                680,
		BackgroundColour:         options.NewRGB(247, 249, 252),
		AssetServer:              &assetserver.Options{Assets: web},
		OnStartup:                application.startup,
		OnShutdown:               application.shutdown,
		Bind:                     []interface{}{application},
		EnableDefaultContextMenu: true,
	}); err != nil {
		slog.Error("Tengeneza CV stopped unexpectedly", "error", err)
		os.Exit(1)
	}
}

func (a *App) startup(ctx context.Context)    { a.desktop.Startup(ctx) }
func (a *App) shutdown(ctx context.Context)   { a.desktop.Shutdown(ctx) }
func (a *App) GetAPIBaseURL() (string, error) { return a.desktop.APIBaseURL() }
